        curr = arr[tp]
               * (s.length === 0 ? n
                                 : n - s[s.length - 1] - 1);
        res = Math.max(res, curr);
    }

    return res;
}

function maxArea(mat)
{
    let n = mat.length, m = mat[0].length;

    // Array to store matrix
    // as a histogram.
    let arr = new Array(m).fill(0);

    let res = 0;

    // Traverse row by row.
    for (let i = 0; i < n; i++) {
        for (let j = 0; j < m; j++) {
            if (mat[i][j] === 1) {
                arr[j]++;
            }
            else {
                arr[j] = 0;
            }
        }

        res = Math.max(res, getMaxArea(arr));
    }

    return res;
}

